-- Reconcile BMN announcement identities after import: one published canonical row per document.
-- reconcile Pengumuman Penetapan Pemenang Lelang BMN
SET @bmn_id := (SELECT MIN(id) FROM #__content WHERE JSON_UNQUOTE(JSON_EXTRACT(metadata, '$.bmn_document_url')) COLLATE utf8mb4_unicode_ci = CONVERT(0x68747470733A2F2F64726976652E676F6F676C652E636F6D2F66696C652F642F314B4447647A7762754B30576271755F334D6C626A485472704467706C335464362F766965773F7573703D73686172696E67 USING utf8mb4) COLLATE utf8mb4_unicode_ci OR alias COLLATE utf8mb4_unicode_ci = CONVERT(0x70656E67756D756D616E2D70656E65746170616E2D70656D656E616E672D6C656C616E672D626D6E USING utf8mb4) COLLATE utf8mb4_unicode_ci OR LOWER(TRIM(title)) COLLATE utf8mb4_unicode_ci = LOWER(TRIM(CONVERT(0x50656E67756D756D616E2050656E65746170616E2050656D656E616E67204C656C616E6720424D4E USING utf8mb4))) COLLATE utf8mb4_unicode_ci);
UPDATE #__content SET state = -2, modified = NOW(), note = 'duplicate-bmn-reconciled' WHERE id <> @bmn_id AND (JSON_UNQUOTE(JSON_EXTRACT(metadata, '$.bmn_document_url')) COLLATE utf8mb4_unicode_ci = CONVERT(0x68747470733A2F2F64726976652E676F6F676C652E636F6D2F66696C652F642F314B4447647A7762754B30576271755F334D6C626A485472704467706C335464362F766965773F7573703D73686172696E67 USING utf8mb4) COLLATE utf8mb4_unicode_ci OR alias COLLATE utf8mb4_unicode_ci = CONVERT(0x70656E67756D756D616E2D70656E65746170616E2D70656D656E616E672D6C656C616E672D626D6E USING utf8mb4) COLLATE utf8mb4_unicode_ci OR LOWER(TRIM(title)) COLLATE utf8mb4_unicode_ci = LOWER(TRIM(CONVERT(0x50656E67756D756D616E2050656E65746170616E2050656D656E616E67204C656C616E6720424D4E USING utf8mb4))) COLLATE utf8mb4_unicode_ci);
UPDATE #__content SET created = CONVERT(0x323032362D30362D31312030393A30303A3030 USING utf8mb4), publish_up = CONVERT(0x323032362D30362D31312030393A30303A3030 USING utf8mb4), modified = NOW() WHERE id = @bmn_id;
